{"path": "/tmp/sv-b91cc58699784fea812859bbebfa3dcd/RecipeHub/Services/RecipeService.cs", "file_text": "using RecipeHub.Models;

namespace RecipeHub.Services;

public class RecipeService
{
    private readonly List<Recipe> _recipes = new()
    {
        new Recipe { Id = 1, Title = "Classic Margherita Pizza", Category = "Italian", Ingredients = "Pizza dough\nSan Marzano tomatoes\nFresh mozzarella\nFresh basil\nOlive oil\nSalt", Steps = "1. Preheat oven to 475°F (245°C).\n2. Roll out dough on a floured surface.\n3. Spread crushed tomatoes evenly.\n4. Tear mozzarella and distribute over sauce.\n5. Bake for 10-12 minutes until crust is golden.\n6. Top with fresh basil and a drizzle of olive oil.", AverageRating = 4.5, RatingCount = 12 },
        new Recipe { Id = 2, Title = "Spaghetti Carbonara", Category = "Italian", Ingredients = "Spaghetti\nGuanciale (or pancetta)\nEggs\nPecorino Romano\nBlack pepper", Steps = "1. Cook spaghetti in salted boiling water.\n2. Crisp guanciale in a pan.\n3. Whisk eggs with grated pecorino and pepper.\n4. Toss hot pasta with guanciale.\n5. Remove from heat, add egg mixture and toss quickly.\n6. Serve immediately with extra pecorino.", AverageRating = 4.8, RatingCount = 20 },
        new Recipe { Id = 3, Title = "Chicken Tikka Masala", Category = "Indian", Ingredients = "Chicken thighs\nYogurt\nGaram masala\nTurmeric\nCumin\nCoriander\nTomato sauce\nHeavy cream\nGarlic\nGinger", Steps = "1. Marinate chicken in yogurt and spices for 2 hours.\n2. Grill or broil chicken until charred.\n3. Sauté garlic and ginger in oil.\n4. Add tomato sauce and spices, simmer 15 minutes.\n5. Add cream and cooked chicken.\n6. Simmer 10 minutes and serve with rice or naan.", AverageRating = 4.7, RatingCount = 15 },
        new Recipe { Id = 4, Title = "Vegetable Pad Thai", Category = "Asian", Ingredients = "Rice noodles\nTofu\nBean sprouts\nGreen onions\nPeanuts\nLime\nTamarind paste\nFish sauce\nSugar\nChili flakes", Steps = "1. Soak rice noodles in warm water 30 minutes.\n2. Press and cube tofu, pan-fry until golden.\n3. Make sauce: mix tamarind, fish sauce, sugar.\n4. Stir-fry noodles with sauce.\n5. Add tofu and bean sprouts.\n6. Serve with crushed peanuts and lime wedge.", AverageRating = 4.3, RatingCount = 8 },
        new Recipe { Id = 5, Title = "Beef Tacos", Category = "Mexican", Ingredients = "Ground beef\nTaco seasoning\nCorn tortillas\nLettuce\nTomatoes\nCheddar cheese\nSour cream\nSalsa", Steps = "1. Brown ground beef in a skillet.\n2. Add taco seasoning and water, simmer 5 minutes.\n3. Warm tortillas in a dry pan.\n4. Assemble tacos with beef and toppings.\n5. Serve with salsa and sour cream.", AverageRating = 4.2, RatingCount = 10 },
        new Recipe { Id = 6, Title = "Chocolate Lava Cake", Category = "Desserts", Ingredients = "Dark chocolate\nButter\nEggs\nSugar\nFlour\nVanilla extract", Steps = "1. Preheat oven to 425°F (220°C).\n2. Melt chocolate and butter together.\n3. Whisk eggs and sugar until thick.\n4. Fold in chocolate mixture and flour.\n5. Pour into greased ramekins.\n6. Bake 12-14 minutes until edges are set but center jiggles.\n7. Invert onto plates and serve immediately.", AverageRating = 4.9, RatingCount = 25 },
        new Recipe { Id = 7, Title = "Guacamole", Category = "Mexican", Ingredients = "Avocados\nLime juice\nCilantro\nRed onion\nJalapeño\nTomato\nSalt\nGarlic", Steps = "1. Halve and pit avocados, scoop into bowl.\n2. Mash to desired consistency.\n3. Dice onion, tomato, and jalapeño.\n4. Mix in lime juice, cilantro, and diced vegetables.\n5. Season with salt and garlic.\n6. Serve with tortilla chips.", AverageRating = 4.4, RatingCount = 18 },
        new Recipe { Id = 8, Title = "Miso Ramen", Category = "Asian", Ingredients = "Ramen noodles\nMiso paste\nChicken broth\nSoy sauce\nSesame oil\nSoft-boiled egg\nGreen onions\nCorn\nNori\nChashu pork", Steps = "1. Bring chicken broth to a simmer.\n2. Dissolve miso paste into broth.\n3. Season with soy sauce and sesame oil.\n4. Cook ramen noodles separately.\n5. Place noodles in bowl, ladle broth over.\n6. Top with egg, chashu, corn, nori, and green onions.", AverageRating = 4.6, RatingCount = 14 },
    };

    private readonly List<RecipeCategory> _categories = new()
    {
        new RecipeCategory { Name = "Italian", Description = "Classic pasta, pizza, and Mediterranean flavors", Icon = "🍝", RecipeCount = 2 },
        new RecipeCategory { Name = "Indian", Description = "Rich curries, spices, and aromatic dishes", Icon = "🍛", RecipeCount = 1 },
        new RecipeCategory { Name = "Asian", Description = "Noodles, stir-fries, and umami-rich dishes", Icon = "🍜", RecipeCount = 2 },
        new RecipeCategory { Name = "Mexican", Description = "Tacos, salsas, and vibrant Latin flavors", Icon = "🌮", RecipeCount = 2 },
        new RecipeCategory { Name = "Desserts", Description = "Sweet treats, cakes, and indulgent delights", Icon = "🍰", RecipeCount = 1 },
    };

    public List<RecipeCategory> GetCategories() => _categories;

    public List<Recipe> GetRecipesByCategory(string category) =>
        _recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public Recipe? GetRecipeById(int id) => _recipes.FirstOrDefault(r => r.Id == id);

    public void SubmitRating(int recipeId, int stars)
    {
        var recipe = _recipes.FirstOrDefault(r => r.Id == recipeId);
        if (recipe is not null && stars >= 1 && stars <= 5)
        {
            var totalStars = recipe.AverageRating * recipe.RatingCount;
            recipe.RatingCount++;
            recipe.AverageRating = Math.Round((totalStars + stars) / recipe.RatingCount, 1);
        }
    }

    public void AddRecipe(RecipeSubmission submission)
    {
        var newId = _recipes.Max(r => r.Id) + 1;
        _recipes.Add(new Recipe
        {
            Id = newId,
            Title = submission.Title,
            Category = submission.Category,
            Ingredients = submission.Ingredients,
            Steps = submission.Steps,
            AverageRating = 0,
            RatingCount = 0
        });

        var category = _categories.FirstOrDefault(c => c.Name == submission.Category);
        if (category is not null)
            category.RecipeCount++;
    }
}
"}

