@using RecipeHub.Services
@inject RecipeService RecipeService

<div class="card mt-3">
    <div class="card-body">
        <h5 class="card-title">Rate this Recipe</h5>

        @if (HasRated)
        {
            <div class="alert alert-success py-2">
                Thanks for rating! You gave this recipe @SelectedRating star@(SelectedRating == 1 ? "" : "s").
            </div>
        }

        <div class="star-rating" style="font-size: 2rem; cursor: pointer;">
            @for (int i = 1; i <= 5; i++)
            {
                var starValue = i;
                <span class="@(i <= (HasRated ? SelectedRating : HoverRating) ? "text-warning" : "text-muted")"
                      @onclick="() => Rate(starValue)"
                      @onmouseover="() => Hover(starValue)"
                      @onmouseout="ResetHover"
                      role="button"
                      title="@starValue star@(starValue == 1 ? "" : "s")">★</span>
            }
        </div>

        @{
            var recipe = RecipeService.GetRecipeById(RecipeId);
        }
        @if (recipe is not null && recipe.RatingCount > 0)
        {
            <small class="text-muted">
                Average: @recipe.AverageRating / 5 (@recipe.RatingCount ratings)
            </small>
        }
    </div>
</div>

@code {
    [Parameter]
    public int RecipeId { get; set; }

    private int HoverRating { get; set; }
    private int SelectedRating { get; set; }
    private bool HasRated { get; set; }

    private void Rate(int stars)
    {
        if (HasRated) return;
        SelectedRating = stars;
        HasRated = true;
        RecipeService.SubmitRating(RecipeId, stars);
    }

    private void Hover(int stars)
    {
        if (!HasRated)
            HoverRating = stars;
    }

    private void ResetHover()
    {
        if (!HasRated)
            HoverRating = 0;
    }
}

